/* ------------------------------------------------------------------ */
/* Theme: "bullion ledger" -- ink-black background, brass/gold accent, */
/* a serif for prices (weight, gravity) and a monospace for the data   */
/* columns (this reads like a trading ledger, not a marketing page).   */
/* ------------------------------------------------------------------ */
const COLORS = {
  ink: "#12100D",
  inkRaised: "#1B1712",
  inkLine: "#2C261C",
  parchment: "#EDE6D6",
  parchmentDim: "#A89C86",
  brass: "#C9A15A",
  brassBright: "#E8C27E",
  silver: "#D8DCE0",
  buy: "#7FA37A",
  sell: "#B85C4A",
  hold: "#8A8070",
};

const fmtINR = (n) =>
  n == null ? "—" : `\u20B9${Number(n).toLocaleString("en-IN", { maximumFractionDigits: 0 })}`;
const fmtPct = (n, digits = 1) =>
  n == null ? "—" : `${(n * 100).toFixed(digits)}%`;
const fmtSigned = (n, digits = 2) =>
  n == null ? "—" : `${n >= 0 ? "+" : ""}${Number(n).toFixed(digits)}`;

const GLOSSARY = {
  "Signal": "The model's daily call: BUY, SELL, or HOLD, derived from its predicted price move for the next trading day.",
  "Confidence score": "How large the model's predicted move is relative to typical daily noise -- effectively a signal-to-noise ratio, not a probability of being right. A high score means \u201cthis move looks big next to the usual daily wobble,\u201d not \u201cthis is certain.\u201d",
  "Entry price": "The price at which a BUY or SELL signal is evaluated -- the prior day's close.",
  "Stop loss": "The price at which an open position is cut to limit the loss if the market moves the wrong way.",
  "Target": "The price at which an open position is closed to lock in a gain if the market moves the right way.",
  "Directional accuracy": "Of the days the model called a clear up or down move, the share where the market actually moved that way. 50% is chance; it's the honest baseline on data with no real structure.",
  "Walk-forward": "A testing method where the model only ever sees data before the day it's predicting -- never a future price -- so results can't be inflated by hindsight.",
  "Meta-learner": "A small model that blends the ARIMA and XGBoost sub-models' forecasts into one final prediction, learning how much to trust each one.",
  "Buy-and-hold": "The benchmark of simply buying once and holding, used to check whether the strategy's trading actually adds value over doing nothing.",
};

function GlossaryTerm({ term, children }) {
  const [open, setOpen] = useState(false);
  return (
    <span style={{ position: "relative", display: "inline-block" }}>
      <span
        onClick={() => setOpen((o) => !o)}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
        style={{
          borderBottom: `1px dotted ${COLORS.brass}`,
          cursor: "help",
          color: COLORS.brassBright,
        }}
      >
        {children}
      </span>
      {open && (
        <span
          style={{
            position: "absolute",
            bottom: "calc(100% + 8px)",
            left: "50%",
            transform: "translateX(-50%)",
            width: 260,
            background: COLORS.inkRaised,
            border: `1px solid ${COLORS.inkLine}`,
            borderRadius: 4,
            padding: "10px 12px",
            fontSize: 12.5,
            lineHeight: 1.5,
            color: COLORS.parchment,
            fontFamily: "'Georgia', serif",
            zIndex: 20,
            boxShadow: "0 8px 24px rgba(0,0,0,0.5)",
          }}
        >
          {GLOSSARY[term]}
        </span>
      )}
    </span>
  );
}

function SignalBadge({ signal, size = "md" }) {
  const map = {
    BUY: { color: COLORS.buy, Icon: TrendingUp, label: "BUY" },
    SELL: { color: COLORS.sell, Icon: TrendingDown, label: "SELL" },
    HOLD: { color: COLORS.hold, Icon: Minus, label: "HOLD" },
  };
  const { color, Icon, label } = map[signal] || map.HOLD;
  const pad = size === "lg" ? "8px 18px" : "4px 10px";
  const fontSize = size === "lg" ? 15 : 12;
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        padding: pad,
        borderRadius: 3,
        border: `1px solid ${color}`,
        color,
        fontFamily: "'JetBrains Mono', 'Courier New', monospace",
        fontWeight: 600,
        fontSize,
        letterSpacing: "0.08em",
      }}
    >
      <Icon size={size === "lg" ? 16 : 13} />
      {label}
    </span>
  );
}

function Nav({ page, setPage }) {
  const items = [
    { id: "home", label: "Home", Icon: HomeIcon },
    { id: "predictor", label: "Predictor", Icon: BookOpen },
    { id: "market", label: "Market Prediction", Icon: ChartIcon },
  ];
  return (
    <div
      style={{
        display: "flex",
        gap: 4,
        borderBottom: `1px solid ${COLORS.inkLine}`,
        padding: "0 4px",
        marginBottom: 32,
      }}
    >
      {items.map(({ id, label, Icon }) => (
        <button
          key={id}
          onClick={() => setPage(id)}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 7,
            background: "none",
            border: "none",
            borderBottom: page === id ? `2px solid ${COLORS.brass}` : "2px solid transparent",
            color: page === id ? COLORS.brassBright : COLORS.parchmentDim,
            padding: "12px 16px",
            fontSize: 13.5,
            fontFamily: "'JetBrains Mono', 'Courier New', monospace",
            letterSpacing: "0.04em",
            cursor: "pointer",
            transition: "color 0.15s",
          }}
        >
          <Icon size={14} />
          {label.toUpperCase()}
        </button>
      ))}
    </div>
  );
}

