/* ------------------------------------------------------------------ */
function HomePage({ setPage }) {
  return (
    <div>
      <div style={{ maxWidth: 640, marginBottom: 56 }}>
        <div
          style={{
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: 11,
            letterSpacing: "0.16em",
            color: COLORS.brass,
            marginBottom: 14,
          }}
        >
          MCX SILVER &middot; ALGORITHMIC SIGNAL LEDGER
        </div>
        <h1
          style={{
            fontFamily: "'Georgia', serif",
            fontSize: 44,
            fontWeight: 400,
            color: COLORS.parchment,
            lineHeight: 1.15,
            margin: "0 0 20px",
          }}
        >
          Silver Options Predictor
        </h1>
        <p style={{ fontSize: 16, lineHeight: 1.7, color: COLORS.parchmentDim, fontFamily: "'Georgia', serif" }}>
          A daily BUY / SELL / HOLD signal for MCX Silver, produced by a walk-forward
          ensemble of ARIMA, XGBoost, and a meta-learner &mdash; the same pipeline this
          project uses for its real backtests, run here end-to-end and shown honestly,
          noise and all.
        </p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
        <Card onClick={() => setPage("predictor")}>
          <div style={{ color: COLORS.brass, fontSize: 11, letterSpacing: "0.1em", fontFamily: "'JetBrains Mono', monospace", marginBottom: 10 }}>
            01 &mdash; THE PREDICTOR
          </div>
          <h3 style={{ fontFamily: "'Georgia', serif", fontSize: 22, color: COLORS.parchment, margin: "0 0 10px" }}>
            How a signal gets made
          </h3>
          <p style={{ fontSize: 14, color: COLORS.parchmentDim, lineHeight: 1.6, margin: "0 0 16px" }}>
            A plain-English walk from raw prices to today's actual signal &mdash; every
            term explained, nothing assumed.
          </p>
          <CardLink>Walk through it <ChevronRight size={14} /></CardLink>
        </Card>

        <Card onClick={() => setPage("market")}>
          <div style={{ color: COLORS.brass, fontSize: 11, letterSpacing: "0.1em", fontFamily: "'JetBrains Mono', monospace", marginBottom: 10 }}>
            02 &mdash; MARKET PREDICTION
          </div>
          <h3 style={{ fontFamily: "'Georgia', serif", fontSize: 22, color: COLORS.parchment, margin: "0 0 10px" }}>
            The backtest, visualized
          </h3>
          <p style={{ fontSize: 14, color: COLORS.parchmentDim, lineHeight: 1.6, margin: "0 0 16px" }}>
            {PIPELINE_DATA.nPredictions} real walk-forward predictions, charted against
            what actually happened, plus the strategy-vs-buy-and-hold ledger.
          </p>
          <CardLink>See the chart <ChevronRight size={14} /></CardLink>
        </Card>
      </div>

      <div
        style={{
          marginTop: 48,
          paddingTop: 24,
          borderTop: `1px solid ${COLORS.inkLine}`,
          fontSize: 12.5,
          color: COLORS.parchmentDim,
          fontFamily: "'Georgia', serif",
          lineHeight: 1.7,
          maxWidth: 640,
        }}
      >
        Market Prediction now runs the project's real pipeline (feature engineering,
        walk-forward ARIMA + XGBoost + meta-learner, real signal engine, real vectorbt
        backtest) end-to-end &mdash; not a simplified in-browser stand-in. Because there's
        no live MCX feed reachable from this environment, it's run against the project's
        own synthetic price generator rather than real market history; every number you
        see is the honest output of that real math on that data, including the ~51%
        directional accuracy, which is the <em>correct</em> result on data with no genuine
        structure to find.
      </div>
    </div>
  );
}

function Card({ children, onClick }) {
  const [hover, setHover] = useState(false);
  return (
    <div
      onClick={onClick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        background: COLORS.inkRaised,
        border: `1px solid ${hover ? COLORS.brass : COLORS.inkLine}`,
        borderRadius: 4,
        padding: 26,
        cursor: "pointer",
        transition: "border-color 0.15s",
      }}
    >
      {children}
    </div>
  );
}

function CardLink({ children }) {
  return (
    <div
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 4,
        color: COLORS.brassBright,
        fontFamily: "'JetBrains Mono', monospace",
        fontSize: 12.5,
      }}
    >
      {children}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* PREDICTOR                                                            */
/* ------------------------------------------------------------------ */
function PredictorPage() {
  const latest = PIPELINE_DATA.latestSignal;
  const steps = [
    {
      title: "Gather the raw prices",
      body: "Start with MCX Silver's daily open/high/low/close, plus related series (COMEX Silver, USD/INR, the Dollar Index) that tend to move together with it.",
    },
    {
      title: "Engineer features",
      body: "Turn raw prices into signals a model can use: rolling volatility, momentum, and cross-market spreads (e.g. how far MCX has drifted from its COMEX-implied fair value).",
    },
    {
      title: "Predict with three models, blended",
      body: "An ARIMA model (good at short-term momentum) and an XGBoost model (good at nonlinear patterns across features) each make a forecast; a small meta-learner blends the two into one final predicted price move.",
    },
    {
      title: "Turn the prediction into a signal",
      body: "If the predicted move clears a confidence threshold, it becomes a BUY or SELL; otherwise it's a HOLD. A cooldown period stops the model from flip-flopping on noise.",
    },
  ];

  return (
    <div>
      <h1 style={{ fontFamily: "'Georgia', serif", fontSize: 32, color: COLORS.parchment, fontWeight: 400, marginBottom: 8 }}>
        How a signal gets made
      </h1>
      <p style={{ fontSize: 14.5, color: COLORS.parchmentDim, marginBottom: 40, fontFamily: "'Georgia', serif", maxWidth: 620 }}>
        Four steps, raw prices to a call you could act on. Hover any underlined term for
        a plain-English definition.
      </p>

      <div style={{ marginBottom: 48 }}>
        {steps.map((s, i) => (
          <div key={i} style={{ display: "flex", gap: 20, marginBottom: 28 }}>
            <div
              style={{
                fontFamily: "'Georgia', serif",
                fontSize: 22,
                color: COLORS.brass,
                width: 36,
                flexShrink: 0,
              }}
            >
              {String(i + 1).padStart(2, "0")}
            </div>
            <div>
              <h4 style={{ fontFamily: "'Georgia', serif", fontSize: 17, color: COLORS.parchment, margin: "0 0 6px" }}>
                {s.title}
              </h4>
              <p style={{ fontSize: 14, color: COLORS.parchmentDim, lineHeight: 1.6, margin: 0, maxWidth: 560 }}>
                {s.body}
              </p>
            </div>
          </div>
        ))}
      </div>

      <div
        style={{
          background: COLORS.inkRaised,
          border: `1px solid ${COLORS.inkLine}`,
          borderRadius: 4,
          padding: 24,
          maxWidth: 480,
        }}
      >
        <div style={{ fontSize: 11, letterSpacing: "0.1em", color: COLORS.brass, fontFamily: "'JetBrains Mono', monospace", marginBottom: 14 }}>
          MOST RECENT REAL SIGNAL &middot; {latest.date}
        </div>
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 16 }}>
          <SignalBadge signal={latest.signal} size="lg" />
          <span style={{ fontFamily: "'Georgia', serif", fontSize: 26, color: COLORS.parchment }}>
            {fmtINR(latest.entryPrice)}
          </span>
        </div>
        <Row label={<GlossaryTerm term="Entry price">Entry price</GlossaryTerm>} value={fmtINR(latest.entryPrice)} />
        <Row label={<GlossaryTerm term="Stop loss">Stop loss</GlossaryTerm>} value={fmtINR(latest.stopLoss)} />
        <Row label={<GlossaryTerm term="Target">Target</GlossaryTerm>} value={fmtINR(latest.target)} />
        <Row
          label="Predicted move"
          value={latest.predictedReturn == null ? "—" : fmtPct(latest.predictedReturn, 3)}
        />
        <div style={{ fontSize: 11.5, color: COLORS.parchmentDim, marginTop: 14, fontFamily: "'Georgia', serif", lineHeight: 1.5 }}>
          Pulled directly from the real pipeline's most recent walk-forward row &mdash;
          not a hardcoded example.
        </div>
      </div>
    </div>
  );
}

function Row({ label, value }) {
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        padding: "7px 0",
        borderBottom: `1px solid ${COLORS.inkLine}`,
        fontSize: 13,
      }}
    >
      <span style={{ color: COLORS.parchmentDim, fontFamily: "'Georgia', serif" }}>{label}</span>
      <span style={{ color: COLORS.parchment, fontFamily: "'JetBrains Mono', monospace" }}>{value}</span>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* MARKET PREDICTION                                                    */
/* ------------------------------------------------------------------ */
function MarketPredictionPage() {
  const series = PIPELINE_DATA.series;
  const [windowSize, setWindowSize] = useState(Math.min(90, series.length));

  const visible = useMemo(() => series.slice(-windowSize), [series, windowSize]);

  const chartData = visible.map((r) => ({
    date: r.date,
    Actual: r.actualPrice,
    Predicted: r.predictedPrice,
  }));

  const cmp = PIPELINE_DATA.backtestComparison;
  const metricRows = [
    ["Total return", "total_return_pct", (v) => fmtSigned(v, 2) + "%"],
    ["Sharpe ratio", "sharpe_ratio", (v) => fmtSigned(v, 2)],
    ["Max drawdown", "max_drawdown_pct", (v) => (v == null ? "—" : v.toFixed(2) + "%")],
    ["Win rate", "win_rate_pct", (v) => (v == null ? "—" : v.toFixed(1) + "%")],
    ["Total trades", "total_trades", (v) => (v == null ? "—" : Math.round(v))],
  ];

  return (
    <div>
      <h1 style={{ fontFamily: "'Georgia', serif", fontSize: 32, color: COLORS.parchment, fontWeight: 400, marginBottom: 8 }}>
        The backtest, visualized
      </h1>
      <p style={{ fontSize: 14.5, color: COLORS.parchmentDim, marginBottom: 8, fontFamily: "'Georgia', serif", maxWidth: 640 }}>
        {PIPELINE_DATA.nPredictions} real <GlossaryTerm term="Walk-forward">walk-forward</GlossaryTerm> predictions
        from the actual ARIMA + XGBoost + <GlossaryTerm term="Meta-learner">meta-learner</GlossaryTerm> ensemble,
        run against the project's own synthetic price series (no live MCX feed reachable
        here). The dashed line is what the model predicted the next day's close would be,
        known only from prior days &mdash; never a peek at the future.
      </p>
      <p style={{ fontSize: 12.5, color: COLORS.parchmentDim, marginBottom: 28, fontFamily: "'Georgia', serif", maxWidth: 640, fontStyle: "italic" }}>
        Honest framing: synthetic price data has no genuine predictive structure by design
        &mdash; roughly 50% <GlossaryTerm term="Directional accuracy">directional accuracy</GlossaryTerm> here
        is the <em>correct</em> result, proving the walk-forward harness isn't leaking
        future information into training, not a shortcoming of the model.
      </p>

      <div style={{ display: "flex", gap: 24, marginBottom: 20, flexWrap: "wrap" }}>
        <StatCard label="Directional accuracy" value={fmtPct(PIPELINE_DATA.directionalAccuracy)} />
        <StatCard label="Avg. price error" value={fmtPct(PIPELINE_DATA.avgAbsPctError)} />
        <StatCard label="Predictions" value={PIPELINE_DATA.nPredictions} />
      </div>

      <div style={{ marginBottom: 12, display: "flex", alignItems: "center", gap: 12 }}>
        <span style={{ fontSize: 12, color: COLORS.parchmentDim, fontFamily: "'JetBrains Mono', monospace" }}>
          ZOOM
        </span>
        <input
          type="range"
          min={20}
          max={series.length}
          value={windowSize}
          onChange={(e) => setWindowSize(Number(e.target.value))}
          style={{ flex: 1, accentColor: COLORS.brass }}
        />
        <span style={{ fontSize: 12, color: COLORS.parchment, fontFamily: "'JetBrains Mono', monospace", width: 90, textAlign: "right" }}>
          last {windowSize} days
        </span>
      </div>

      <div
        style={{
          background: COLORS.inkRaised,
          border: `1px solid ${COLORS.inkLine}`,
          borderRadius: 4,
          padding: "20px 16px 8px",
          marginBottom: 32,
        }}
      >
        <ResponsiveContainer width="100%" height={340}>
          <LineChart data={chartData} margin={{ top: 4, right: 12, left: 0, bottom: 4 }}>
            <CartesianGrid stroke={COLORS.inkLine} strokeDasharray="2 4" vertical={false} />
            <XAxis
              dataKey="date"
              tick={{ fill: COLORS.parchmentDim, fontSize: 10, fontFamily: "monospace" }}
              tickLine={false}
              axisLine={{ stroke: COLORS.inkLine }}
              minTickGap={40}
            />
            <YAxis
              tick={{ fill: COLORS.parchmentDim, fontSize: 10, fontFamily: "monospace" }}
              tickLine={false}
              axisLine={{ stroke: COLORS.inkLine }}
              domain={["auto", "auto"]}
              tickFormatter={(v) => `\u20B9${(v / 1000).toFixed(0)}k`}
            />
            <Tooltip
              contentStyle={{
                background: COLORS.ink,
                border: `1px solid ${COLORS.brass}`,
                borderRadius: 4,
                fontFamily: "monospace",
                fontSize: 12,
              }}
              labelStyle={{ color: COLORS.brassBright }}
              formatter={(value, name) => [fmtINR(value), name]}
            />
            <Line type="monotone" dataKey="Actual" stroke={COLORS.silver} strokeWidth={2} dot={false} />
            <Line type="monotone" dataKey="Predicted" stroke={COLORS.brassBright} strokeWidth={1.5} strokeDasharray="5 3" dot={false} />
          </LineChart>
        </ResponsiveContainer>
      </div>

      <h3 style={{ fontFamily: "'Georgia', serif", fontSize: 19, color: COLORS.parchment, marginBottom: 14 }}>
        Strategy vs. buy-and-hold
      </h3>
      <div
        style={{
          background: COLORS.inkRaised,
          border: `1px solid ${COLORS.inkLine}`,
          borderRadius: 4,
          overflow: "hidden",
          marginBottom: 8,
        }}
      >
        <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: "'JetBrains Mono', monospace", fontSize: 12.5 }}>
          <thead>
            <tr style={{ borderBottom: `1px solid ${COLORS.inkLine}` }}>
              <th style={thStyle}>Metric</th>
              <th style={thStyle}>Strategy</th>
              <th style={thStyle}>Buy &amp; hold</th>
            </tr>
          </thead>
          <tbody>
            {metricRows.map(([label, key, fmt]) => (
              <tr key={key} style={{ borderBottom: `1px solid ${COLORS.inkLine}` }}>
                <td style={tdStyle}>{label}</td>
                <td style={{ ...tdStyle, color: COLORS.parchment }}>{fmt(cmp[key]?.strategy)}</td>
                <td style={{ ...tdStyle, color: COLORS.parchment }}>{fmt(cmp[key]?.buyAndHold)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p style={{ fontSize: 11.5, color: COLORS.parchmentDim, fontFamily: "'Georgia', serif", fontStyle: "italic", maxWidth: 620 }}>
        Real vectorbt backtest output on synthetic (no-structure) data &mdash; both legs
        losing money here is expected and honest, not a bug: there's no real edge to find
        in a random walk, and the strategy pays more in fees/slippage from trading than
        buy-and-hold's single position does.
      </p>
    </div>
  );
}

const thStyle = { textAlign: "left", padding: "10px 16px", color: COLORS.brass, fontWeight: 600, fontSize: 11, letterSpacing: "0.05em" };
const tdStyle = { padding: "9px 16px", color: COLORS.parchmentDim };

function StatCard({ label, value }) {
  return (
    <div
      style={{
        background: COLORS.inkRaised,
        border: `1px solid ${COLORS.inkLine}`,
        borderRadius: 4,
        padding: "14px 20px",
        minWidth: 140,
      }}
    >
      <div style={{ fontSize: 10.5, letterSpacing: "0.08em", color: COLORS.parchmentDim, fontFamily: "'JetBrains Mono', monospace", marginBottom: 6 }}>
        {label.toUpperCase()}
      </div>
      <div style={{ fontFamily: "'Georgia', serif", fontSize: 24, color: COLORS.parchment }}>{value}</div>
    </div>
  );
}

